  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5+Math.sin(sx*0.22-sy*0.18+t*1.5)*0.3)*1.5)*0.3;
  const blend=reaction*0.7+cell*0.3,v=blend*0.5+0.5;
